class TestUser:
    def __init__(self, username, age):
        self.username = username
        self.age = age

    def is_adult(self):
        return self.age >= 18


class AdminUser(TestUser):
    def __init__(self, username, age, permissions):
        # вызови super().__init__(...) для username и age
        # сохрани permissions в self.permissions
        pass

    def has_permission(self, name):
        # верни True, если name есть в self.permissions, иначе False
        pass

tests:
def test_admin_inherits_username_and_age():
    admin = AdminUser("ivan", 30, ["view_reports"])
    assert admin.username == "ivan", "AdminUser должен получить username через super().__init__()"
    assert admin.age == 30, "AdminUser должен получить age через super().__init__()"


def test_admin_is_adult_inherited():
    admin = AdminUser("ivan", 30, [])
    assert admin.is_adult() is True, "AdminUser должен унаследовать метод is_adult() без переопределения"


def test_has_permission_true():
    admin = AdminUser("ivan", 30, ["view_reports", "edit_users"])
    assert admin.has_permission("edit_users") is True, "edit_users есть в списке permissions"


def test_has_permission_false():
    admin = AdminUser("ivan", 30, ["view_reports"])
    assert admin.has_permission("delete_users") is False, "delete_users нет в списке permissions"
